function loadPreCliTestReworkSetup(mocks, spies) {
    var realPrHelper = loadModule(
        'js/common/pullRequest.js',
        null,
        {
            cli_execute_command: function() { return ''; },
            file_read: function() { return null; },
            file_write: function() {},
            file_delete: function() {}
        }
    );

