        },
        fetchDiscussionsAndRawData: function() { return { markdown: '', rawThreads: [] }; }
    };

    var gitOpsStub = {
        checkoutPRBranch: function() {},
        detectMergeConflicts: function() { return []; },
        getPRDiff: function() { return ''; },
