    return loadModule('js/preCliTestReworkSetup.js', makeRequire(moduleMap), allMocks);
}

function makeSpies() {
    return {
        createPullRequestCalls: [],
        ensureClosesLineCalls: [],
        scmCreatePrCalls: []
